&quot;) #storm summary for creating storm ids in file names storm_summary &lt;- rbind(storm_summary, data.frame(Year = year, Storms = length(storm_ids))) #file naming system is regular within the website hierarchy, so download all zip shapefiles using the engineered storm names for (storm_id in storm_ids) { zip_name &lt;- paste0(storm_id, year, &quot;_best_track.zip&quot;) url &lt;- paste0(base_zip, zip_name) dest &lt;- file.path(base_shape_dir, zip_name) #set outpath based on string specified earlier cat(&quot; downloading:&quot;, zip_name, &quot;
