m id file shp &lt;- shp %&gt;% mutate(storm_id = file_prefix) #overwrite shapefile st_write(shp, shp_path, delete_dsn = TRUE, quiet = TRUE) } Date and time need to be consistent between the point and polygon files. #Create a new directory for processed files output_dir &lt;- file.path(base_dir, &quot;processed&quot;) #processing for just the _pts.shp files to normalize dates and times base_dir &lt;- r&quot;(./data/HurricaneRawData/nhc_best_tracks)&quot; output_dir &lt;- file.path(base_dir, &quot;processed&quot;) dir.create(output_dir, showWarnings = FALSE) #get all the shapefiles recursively shp_files &lt;- list.files(base_dir, pattern = &quot;_pts\.shp$&quot;, recursive = TRUE, full.names = TRUE) #recursively alter the pts files to the normalized date and time fields with ids for (shp_path in shp_files) { message(&quot;Processing: &quot;, shp_path) shp &lt;- st_read(shp_path, quiet = TRUE) #files had different formats for dates and times, this normalizes them # important step to combine everything for later analysis shp &lt;- shp %&gt;% mutate( mm = str_pad(as.integer(unname(month_map[tolower(MONTH)])), 2, pad = &quot;0&quot;), dd = str_pad(as.integer(DAY), 2, pad = &quot;0&quot;), hh = str_sub(HHMM, 1, 2), event_id = tolower(paste0(storm_id, mm, dd, hh)) ) #preserve folder structure in output rel_path &lt;- path_rel(shp_path, start = base_dir) out_path &lt;- file.path(output_dir, rel_path) dir_create(dirname(out_path)) #write output st_write(shp, out_path, delete_dsn = TRUE, quiet = TRUE) } ## Warning in CPL_write_ogr(obj, dsn, layer, driver, as.character(dataset_options), : GDAL Error 1: ## ./data/HurricaneRawData/nhc_best_tracks/processed/processed/processed/processed/processed/processed/processed/al01_2011/al012011_pts.shp ## does not appear to be a file or directory. ## Warning in CPL_write_ogr(obj, dsn, layer, driver, as.character(dataset_options), : GDAL Error 1: ## ./data/HurricaneRawData/nhc_best_tracks/processed/processed/processed/processed/processed/pro