ng in CPL_write_ogr(obj, dsn, layer, driver, as.character(dataset_options), : GDAL Error 1: ## ./data/HurricaneRawData/nhc_best_tracks/processed/processed/processed/processed/processed/processed/processed/al28_2020/AL282020_radii.shp ## does not appear to be a file or directory. ## Warning in CPL_write_ogr(obj, dsn, layer, driver, as.character(dataset_options), : GDAL Error 1: ## ./data/HurricaneRawData/nhc_best_tracks/processed/processed/processed/processed/processed/processed/processed/al29_2020/AL292020_radii.shp ## does not appear to be a file or directory. ## Warning in CPL_write_ogr(obj, dsn, layer, driver, as.character(dataset_options), : GDAL Error 1: ## ./data/HurricaneRawData/nhc_best_tracks/processed/processed/processed/processed/processed/processed/processed/al30_2020/AL302020_radii.shp ## does not appear to be a file or directory. ## Warning in CPL_write_ogr(obj, dsn, layer, driver, as.character(dataset_options), : GDAL Error 1: ## ./data/HurricaneRawData/nhc_best_tracks/processed/processed/processed/processed/processed/processed/processed/al31_2020/AL312020_radii.shp ## does not appear to be a file or directory. 4.3.3 Data Manipulation Now that the hurricane files are prepared properly, the associated points data of interest, (in this case hospitals), can be used within the files. THe point files in this example have a series of months and years in columns when surveys were conducted, a latitude and longitude column where we can identify First we load all the storms. #where all the processed files are storms_dir &lt;- r&quot;(./data/HurricaneRawData/nhc_best_tracks/processed)&quot; #get all the radii shapefiles #I settled on radii, because its the reach of the wind shp_files &lt;- list.files(storms_dir, pattern = &quot;_radii\.shp$&quot;, recursive = TRUE, full.names = TRUE) #read and merge them together storms &lt;- lapply(shp_files, function(shp) { suppressWarnings( st_read(shp, quiet = TRUE) %&gt;% select(any_of(cols)) %&gt;% st_transform(4326) %&gt;% st_make_valid() ) }) the_storms &lt;- do.call(rbind, storms) all_storms &lt;- the_storms #make sure the geometries are valid, often times they were unclosed fan shapes all_storms &lt;- st_transform(all_storms, 4326) all_storms &lt;- st_make_valid(all_storms) #get just the date from the storms all_storms$months &lt;- ym(str_sub(all_storms$event_id,5,10)) Now that all the data is loaded and ready, the intersection with all the points of interest needs to be performed and a number of data outputs are created. A long table of storms and intersections with schools. A wide table with the ID’s of the surveyed locations and a matrix of 1’s and 0’s identifying if they were impacted by a storm during the previous 24 months. A table with daily intersection information for the month the survey was conducted. A long table with only intersection information #the website of interest for tracks website &lt;- &#39;https://www.nhc.noaa.gov/gis/archive_besttrack.php&#39; #lookup table with names that was created in an earlier step storm_names_dir &lt;- r&quot;(./data/HurricaneRawData/storm_lookup_table.csv)&quot; ############################################################## #postcode files should have matching column titles to do this in a loop: #id column #long, lat #survey_year, survey_month # make sure that these column names exist long_col &lt;- &quot;long&quot; lat_col &lt;- &quot;lat&quot; survey_id_col &lt;- &quot;hospital_id&quot; survey_year_col &lt;- &quot;survey_year&quot; survey_month_col &lt;- &quot;survey_month&quot; ############################################################# cols &lt;- c(&quot;geometry&quot;, &quot;event_id&quot;, &quot;event_r_id&quot;, &quot;storm_id&quot;) #buffer distances in metres to go around point of interest bufs &lt;- c(0)#, 25000, 50000, 100000) #years of survey dates for table naming conventions years &lt;- c(2023) #this is paried with the above years, should match up! survey_hospitals &lt;- r&quot;(./data/odhf_hospitals.csv)&quot; dirs &lt;- c(survey_hospitals) #results storage hurricane_results &lt;- list() #this is a double loop, the first one goes through each survey year of interest for (k in seq_along(years)){ message(&quot;Naming suffix: &quot;, years[k]) #the second loop applies the buffer size to the survey data for intersection analysis # between storm pathway and survey data for (i in seq_along(bufs)){ message(&quot;Point buffer extent: &quot;, bufs[i]/1000, &quot; km&quot;) #read the survey data survey_data &lt;- read.csv(dirs[k]) # convert the survey data to an sf object for the intersection survey_sf &lt;- st_as_sf( #eliminate the Nas survey_data[!is.na(survey_data[[long_col]]) &amp; !is.na(survey_data[[lat_col]]), ], coords = c(long_col, lat_col), crs = 4326 ) #make sure its the appropriate crs survey_sf &lt;- st_transform(survey_sf, 4326) #apply the buffer to the survey points survey_buffer &lt;- st_buffer(survey_sf, bufs[i]) #create a date type column from the survey year and survey month columns survey_buffer$months &lt;- ym(paste0(survey_buffer[[survey_year_col]], survey_buffer[[survey_month_col]])) survey_buffer$survey_id &lt;- paste(survey_buffer[[survey_id_col]], survey_buffer[[survey_month_col]], survey_buffer[[survey_year_col]], sep=&quot;_&quot;) #get all storms that happen within 30 months of the earliest survey date and the latest survey month of that year # this could be a pretty variable range of dates all_storms_within_range &lt;- all_storms %&gt;% filter(months &gt;= (min(survey_buffer$months)-months(30)) &amp; months &lt;= max(survey_buffer$months)) #do the intersection between the surveys and all of those storms intersection &lt;- st_intersects(survey_buffer, all_storms_within_range, sparse = TRUE) #build the dataframe intersection_df &lt;- map2_dfr( #for each intersection seq_along(intersection), #create a little tibble of point, strom, survey, and if it intersects # creates an association between each poi and storm intersect event and attaches the date of the survey intersection, ~ tibble( point_id = survey_sf[[survey_id_col]][.x], storm_id = all_storms_within_range$event_r_id[.y], survey_date = survey_buffer$months[.x], intersects = 1 ) ) #get the strom names storm_lookup &lt;- read.csv(storm_names_dir, sep=&quot;,&quot;) #preserve the intersection dataframe matrix_df &lt;- intersection_df #get the survey data anew survey_data &lt;- read.csv(dirs[k]) #set blanks to na&#39;s survey_data[survey_data == &quot;&quot;] &lt;- NA #only keep non na points survey_data &lt;- survey_data[!is.na(survey_data[[long_col]]) &amp; !is.na(survey_data[[lat_col]]), ] #convert to data.table survey_data &lt;- as.data.table(survey_data) #organize dates survey_data[, dates := ceiling_date(make_date(survey_year, survey_month, 1), &quot;month&quot;) - days(1)] #convert to data.table matrix_df &lt;- as.data.table(matrix_df) #only interested in the intersections, there shouldn&#39;t be any misses, but just in case matrix_df &lt;- matrix_df[intersects == 1] #set the date column in the matrix_df data frame matrix_df[, year_month := format(ym(str_sub(storm_id, 5, 10)), &quot;%Y%m&quot;)] #only need to know if there is an intersection on that month, # so get unique entries for each poi and month combination matrix_df &lt;- unique(matrix_df, by = c(&quot;point_id&quot;,&quot;survey_date&quot;, &quot;year_month&quot;)) #expand each survey row into last 24 months (month_0 = survey month, month_1 = survey-1, etc) expand_months &lt;- function(d, s_id, survey_month, survey_year) { data.table( survey_id = s_id, survey_year = survey_year, survey_month = survey_month, offset = 0:24, date = format(ceiling_date(d %m-% months(0:24), &quot;month&quot;) - days(1), &quot;%Y%m&quot;) ) } #apply the function # identifies how many months a given month is offset from the 0th month for that pois survey date survey_expanded &lt;- survey_data[, expand_months(dates, get(survey_id_col), survey_month, survey_year), by = c(survey_id_col, survey_year_col, survey_month_col)] survey_expanded$survey_date &lt;- ym(paste0(survey_expanded[[survey_year_col]], survey_expanded[[survey_month_col]])) #join the storms on survey id and the date at year_month result &lt;- matrix_df[survey_expanded, on = c(&quot;point_id&quot; = survey_id_col, &quot;year_month&quot; = &quot;date&quot;)] #add 0&#39;s to the matrix of 1&#39;s and 0&#39;s result[is.na(intersects), intersects := 0] #join storm names for easier identification storm_lookup &lt;- as.data.table(storm_lookup) #storm id and year to cross reference with website. storm_lookup[, storm_id_year := paste0(storm_id, year)] result[, storm_id_year := str_sub(storm_id, 1, 8)] result &lt;- merge( result, storm_lookup[, .(storm_id_year, storm_name)], by = &quot;storm_id_year&quot;, all.x = TRUE ) #pivot to one row per id and columns month_0 to 24\ formula_str &lt;- paste(&quot;survey_id + survey_month + survey_year ~ paste0(&#39;month_&#39;, offset)&quot;) result_months &lt;- dcast( result, as.formula(formula_str), value.var = &quot;intersects&quot;, fun.aggregate = max ) #join the lat and long from the original dataset back for joining later on_vec &lt;- setNames(c(survey_id_col, &quot;survey_year&quot;, &quot;survey_month&quot;), c(&quot;survey_id&quot;, &quot;survey_year&quot;, &quot;survey_month&quot;)) result_months[survey_data, on = on_vec, `:=`(lat = i.lat, long = i.long)] ################### month 0 information day by day ############################### matrix_df &lt;- intersection_df matrix_df &lt;- matrix_df %&gt;% #only intersections filter(intersects == 1) %&gt;% #get date to the day of the storm mutate(year_month_day = ymd(str_sub(storm_id, 5, 12))) %&gt;% mutate(storm_id_long = str_sub(storm_id, 0, 12)) %&gt;% #one row per day, doesn&#39;t matter the wind speed distinct(., point_id, year_month_day,.keep_all=TRUE) %&gt;% #format date as a date again mutate(year_month_day = format(year_month_day, &quot;%Y-%m-%d&quot;)) #get survey data survey_data &lt;- read.csv(dirs[k]) #set blanks to na&#39;s survey_data[survey_data == &quot;&quot;] &lt;- NA #only keep non na points survey_data &lt;- survey_data[!is.na(survey_data[[long_col]]) &amp; !is.na(survey_data[[lat_col]]), ] #assume survey was conducted on the final day of the month, so check every day of the month survey_data$dates &lt;- ceiling_date(make_date(year=survey_data[[survey_year_col]], month = survey_data[[survey_month_col]], day = 1), &quot;month&quot;) - days(1) #expand to every day of the month expand_survey_data &lt;- survey_data %&gt;% rowwise() %&gt;% mutate(days_in_month = list(seq(from = floor_date(dates, &quot;month&quot;), to = dates, by = &quot;1 day&quot;))) %&gt;% unnest(days_in_month) %&gt;% rename(date = days_in_month) %&gt;% mutate(date = format(date,&quot;%Y-%m-%d&quot;)) #join the two datasets of storm data and survey data result_days &lt;- left_join(expand_survey_data, matrix_df, by = c(&quot;date&quot; = &quot;year_month_day&quot;, setNames(&quot;point_id&quot;, survey_id_col))) #add to final dataframe of dataframes key &lt;- paste0(&quot;result_&quot;, bufs[i]/1000, &quot;k_&quot;, years[k]) hurricane_results[[key]] &lt;- list( long = result, wide = result_months, daily = result_days, matrix = matrix_df ) } } ## Naming suffix: 2023 ## Point buffer extent: 0 km ## Processed 858 groups out of 1047. 82% done. Time elapsed: 3s. ETA: 0s.Processed 1047 groups out of 1047. 100% done. Time elapsed: 3s. ETA: 0s.
